  const raw = JSON.parse(readFileSync(file, 'utf8')) as Record<keyof Fees, unknown>;
  const amount = (name: keyof Fees): number => {
    const value = typeof raw[name] === 'string' ? Number(raw[name]) : raw[name];
    if (typeof value !== 'number' || !Number.isFinite(value)) {
      throw new Error(`config/fees.json: ${name} must be a number, got ${JSON.stringify(raw[name])}`);
    }
    return value;
  };
  return {
    handlingFee: amount('handlingFee'),
    giftWrapFee: amount('giftWrapFee'),
    freeHandlingThreshold: amount('freeHandlingThreshold'),
  };
}
